files.machine/machine.config.js:
// @bakers-schema-version 1
// Local host identity. The run budget is set on the machine in the backend;
// server credentials belong to the connection (connections/default.js). An
// `executor` slot here (e.g. `{ use: '@bakers-build/addon-herdr-core' }`)
// overrides every project's executor on this machine.
/** @type {import('@bakers-build/core').MachineConfig} */
export default {
  schema_version: 1,
  machine_id: 'a8c8cf65-e3f7-4cf7-9509-0a9875ace9f6',
  label: 'audit-worker',
};

files.machine/connections/default.js:
// @bakers-schema-version 1
// A bakers.build connection: credentials and optional workspace. Keep this file private.
/** @type {import('@bakers-build/core').ConnectionConfig} */
export default {
  schema_version: 1,
  site: { base_url: 'https://setup.example.test', jsonapi_prefix: '/jsonapi' },

  plugins: [
    { plugin: '@bakers-build/addon-essentials' },
    {
      plugin: '@dropsh/plugin-oauth2',
      export: 'oauth2Plugin',
      with: {
        id: 'bakers',
        default: true,
        type: 'oauth2_device_code',
        scope: 'bb:session',
        client_id: 'bakers-cli',
        device_authorization_url:
          'https://setup.example.test/oauth/device_authorization',
        token_url: 'https://setup.example.test/oauth/token',
      },
    },
  ],
};

